// Stable first-play editorial values, not live statistics. Lists are ordered by initial game value.
export const extraCategories=[];
function pack(id,name,group,icon,brief,metric,basis,raw){const names=raw.split('|');extraCategories.push({id,name,group,icon,brief,metric,basis,cards:names.map((name,i)=>({id:id+'-'+i,name,tag:group,universe:null,score:Math.round(95-i/(names.length-1)*35)}))});}
